program.compute:
options=read('/input/options')
goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal.get('sum_bounds',{})
goal_unique=goal.get('unique',[])
goal_order_by=goal.get('order_by',[])
from itertools import combinations

# We cannot import itertools, so use combinations from builtins as per instructions

# Prepare list of option dicts
opts=options

# Helper to check uniqueness of fields
 def unique_fields(ids,field):
  vals=[]
  for id in ids:
   for o in opts:
    if o['id']==id:
     vals+=[o[field]]
  return len(vals)==len(set(vals))

# Helper to get sum of a field
 def sum_field(ids,field):
  s=0
  for id in ids:
   for o in opts:
    if o['id']==id:
     s+=o[field]
  return s

# Helper to get option by id
 def get_opt(id):
  for o in opts:
   if o['id']==id:
    return o
  return None

# Helper to check requires closure
 def closed_dependencies(ids):
  # For each selected option, all requires must be in ids
  for id in ids:
   o=get_opt(id)
   if o is None:
    return False
   for r in o.get('requires',[]):
    if r not in ids:
     return False
  return True

# Helper to check conflicts
 def no_conflicts(ids):
  # No pair in ids conflicts
  for i in range(len(ids)):
   oi=get_opt(ids[i])
   if oi is None:
    return False
   for j in range(i+1,len(ids)):
    oj=get_opt(ids[j])
    if oj is None:
     return False
    if ids[j] in oi.get('conflicts',[]) or ids[i] in oj.get('conflicts',[]):
     return False
  return True

# Check unique fields
 def check_unique(ids):
  for f in goal_unique:
   if not unique_fields(ids,f):
    return False
  return True

# Check sum bounds
 def check_sum_bounds(ids):
  for f,v in goal_sum_bounds.items():
   s=sum_field(ids,f)
   if 'min' in v and s<v['min']:
    return False
   if 'max' in v and s>v['max']:
    return False
  return True

# Check min/max count
 def check_count(ids):
  l=len(ids)
  if l<goal_min or l>goal_max:
   return False
  return True

# Check order by
 def order_key(id):
  o=get_opt(id)
  if o is None:
   return ()
  return tuple(o[k] for k in goal_order_by)

# Check all goal constraints
 def valid(ids):
  if not check_count(ids):
   return False
  if not check_unique(ids):
   return False
  if not check_sum_bounds(ids):
   return False
  if goal.get('closed_dependencies',False):
   if not closed_dependencies(ids):
    return False
  if goal.get('no_conflicts',False):
   if not no_conflicts(ids):
    return False
  # cover is empty here
  return True

# Try all combinations of size min_count to max_count
result=None
for k in range(goal_min,goal_max+1):
 for comb in combinations(opts,k):
  ids=[o['id'] for o in comb]
  # Check requires closure if needed
  if goal.get('closed_dependencies',False):
   # Add requires recursively
   added=True
   full_ids=ids[:]
   while added:
    added=False
    for id in full_ids[:]:
     o=get_opt(id)
     if o is None:
      continue
     for r in o.get('requires',[]):
      if r not in full_ids:
       full_ids+=[r]
       added=True
   ids=full_ids
  # Check unique
  if not valid(ids):
   continue
  # Check order
  sorted_ids=sorted(ids,key=order_key)
  # Check if sorted_ids equals ids or not? The goal says order_by ascending lexicographic fields, so selection should be ordered by these fields
  # We can reorder selection to sorted_ids
  ids=sorted_ids
  # Final check
  if valid(ids):
   result=ids
   break
 if result is not None:
  break

program.effects:
if result is None:
 status('report')
else:
 existing=read('/output/selection')
 if existing is not None and valid(existing):
  # Already have valid selection, do not overwrite
  if status('report')!='sent':
   send('report','team',existing)
 else:
  write('/output/selection',result)
  send('report','team',result)
 if exists('/tmp/cache'):
  delete('/tmp/cache')
 status('report')

